package com.pathland.view;

/** A `VStack`'s cross-axis alignment (SwiftUI {@code HorizontalAlignment}): the
 *  horizontal position of children within the stack. Position-only — a child's
 *  {@code FILL} size kind stretches, never an alignment. */
public enum HorizontalAlignment {

    LEADING(0),
    CENTER(1),
    TRAILING(2);

    private final int wire;

    HorizontalAlignment(int wire) {
        this.wire = wire;
    }

    public int wire() {
        return wire;
    }
}

package com.pathland.view;

/** An `HStack`'s cross-axis alignment (SwiftUI {@code VerticalAlignment}): the
 *  vertical position of children within the stack. Position-only — a child's
 *  {@code FILL} size kind stretches, never an alignment. */
public enum VerticalAlignment {

    TOP(0),
    CENTER(1),
    BOTTOM(2);

    private final int wire;

    VerticalAlignment(int wire) {
        this.wire = wire;
    }

    public int wire() {
        return wire;
    }
}

package com.pathland.view;

/** A 2D alignment (SwiftUI {@code Alignment} / Compose {@code Alignment}) for
 *  `ZStack` children, grid cells, and the {@code frame} modifier's content
 *  placement. The wire code packs a horizontal and vertical position (spec
 *  PRIMITIVES.md §ZStack); `0`/absent is the default top-leading. Position-only
 *  — a child's {@code FILL} size kind stretches, never an alignment. */
public enum Alignment {

