    void isPingDetectsAMetaPingBatch() {
        // A META::PING heartbeat probe (guest → host), the exact vector-16a bytes.
        byte[] ping = new byte[16 + 16 + 4];
        ping[0] = 'P';
        ping[1] = 'L';
        ping[2] = 'P';
        ping[3] = 'L';
