import { randomUUID } from "node:crypto";
const MAGIC=0x504c504c, VERSION=1, HEADER_SIZE=16, OPCODE_SIZE=16;
const CAT_META=0x04;
const CMD_ENVIRONMENT=0x02, CMD_RESYNC=0x03, CMD_PING=0x04, CMD_PONG=0x05;
const ENV_W=0x0001, ENV_H=0x0002, ENV_ROUTE=0x0003;
const f32 = (v) => { const d = new DataView(new ArrayBuffer(4)); d.setFloat32(0, v, true); return d.getUint32(0, true); };
function batch(opcodes, stringSection=null) {
  const extra = stringSection ? 4 + 4 + stringSection.length : 4;
  const out = new Uint8Array(HEADER_SIZE + opcodes.length*OPCODE_SIZE + extra);
  const v = new DataView(out.buffer);
  v.setUint32(0, MAGIC, true); v.setUint16(4, VERSION, true);
  v.setUint16(6, 0x0000, true); v.setUint32(8, 0, true); v.setUint32(12, opcodes.length, true);
  let pos = HEADER_SIZE;
  for (const [cat,cmd,a,b,c] of opcodes) {
    v.setUint8(pos, cat); v.setUint8(pos+1, cmd); v.setUint16(pos+2, 0, true);
    v.setUint32(pos+4, a, true); v.setUint32(pos+8, b, true); v.setUint32(pos+12, c, true);
    pos += OPCODE_SIZE;
  }
  if (stringSection) { v.setUint32(pos, 4+stringSection.length, true); v.setUint32(pos+4, stringSection.length, true); out.set(stringSection, pos+8); }
  else v.setUint32(pos, 0, true);
  return out;
}
const env = () => batch([[CAT_META,CMD_ENVIRONMENT,ENV_W,f32(1280),0],[CAT_META,CMD_ENVIRONMENT,ENV_H,f32(800),0],[CAT_META,CMD_ENVIRONMENT,ENV_ROUTE,0,0]], new TextEncoder().encode("/"));
const ping = () => batch([[CAT_META,CMD_PING,0,0,0]]);
const resync = () => batch([[CAT_META,CMD_RESYNC,0,0,0]]);
const url = `ws://localhost:8081/_pathland/ws?wid=${randomUUID()}`;
const ws = new WebSocket(url);
ws.binaryType = "arraybuffer";
const t0 = Date.now();
let gotPong = false, gotSnapshot = false;
const recvName = (b) => { const v = new DataView(b.buffer); const count = v.getUint32(12,true); const names=[]; for (let i=0;i<count;i++){ const p=HEADER_SIZE+i*16; const cat=v.getUint8(p), cmd=v.getUint8(p+1); names.push(`cat=${cat} cmd=${cmd}`); } return names.join(","); };
ws.onopen = () => { ws.send(env()); setTimeout(()=>{ console.log("SEND PING +"+(Date.now()-t0)+"ms"); ws.send(ping()); }, 200); };
ws.onmessage = (ev) => {
  const b = new Uint8Array(ev.data);
  const v = new DataView(b.buffer);
  const ops = v.getUint32(12,true);
  const names = recvName(b);
  const isPong = names.includes("cmd=5");
  const isSnapshot = ops > 50;
  if (isPong) gotPong = true;
  if (isSnapshot) gotSnapshot = true;
  console.log("RECV +"+(Date.now()-t0)+"ms ops="+ops+" "+names+" "+(isPong?"<-- PONG":isSnapshot?"<-- SNAPSHOT":""));
  if (isPong) setTimeout(()=>{ console.log("SEND RESYNC +"+(Date.now()-t0)+"ms"); ws.send(resync()); }, 100);
};
ws.onclose = (e) => console.log("CLOSE code="+e.code);
setTimeout(() => {
  console.log("RESULT pong="+gotPong+" snapshot="+gotSnapshot);
  ws.close(); process.exit(gotPong&&gotSnapshot?0:1);
}, 10000);
