import { describe, expect, it } from "vitest";
import { applyBatch } from "../src/apply";
import { parseBatch } from "../src/plpl";
import { CAT_PARAMETER, CAT_TREE, CMD_CREATE_NODE, CMD_INSERT_CHILD, CMD_SET_PROPERTY, COMPONENT_TEXT, COMPONENT_ZSTACK, PROP_Z_INDEX, VAL_F32 } from "../src/constants";
import { buildBatch } from "./plpl.test";

const f32bits = (v: number): number => new Uint32Array(new Float32Array([v]).buffer)[0] ?? 0;

describe("scratch", () => {
  it("debug z-index", () => {
    const r = { byId: new Map<number, Node>() };
    const batch = parseBatch(
      buildBatch([
        [CAT_TREE, CMD_CREATE_NODE, 0, 1, COMPONENT_ZSTACK],
        [CAT_TREE, CMD_CREATE_NODE, 0, 2, COMPONENT_TEXT],
        [CAT_PARAMETER, CMD_SET_PROPERTY, 0, 2, (VAL_F32 << 16) | PROP_Z_INDEX, f32bits(5)],
        [CAT_TREE, CMD_INSERT_CHILD, 0, 1, 2],
      ]),
    );
    applyBatch(batch, r);
    const z = r.byId.get(1) as HTMLElement;
    const child = r.byId.get(2) as HTMLElement;
    console.log("z children:", z.children.length, "child zIndex:", child.style.zIndex);
    const shell = z.children[0] as HTMLElement;
    console.log("shell zIndex:", shell.style.zIndex, "inner:", shell.firstElementChild?.tagName, (shell.firstElementChild as HTMLElement)?.style?.zIndex);
    expect(true).toBe(true);
  });
});

